class Repositorio:
    def __init__(self):
        self.staging = []
        self.commits = []
    def add(self, arquivo):
        if arquivo not in self.staging:
            self.staging.append(arquivo)
    def commit(self, mensagem):
        if not self.staging:
            raise ValueError("Nada para commitar")
        novo = Commit(len(self.commits) + 1, mensagem, self.staging)
        self.commits.append(novo)
        self.staging = []
        return novo

