class MiniGit:
    def __init__(self):
        self.staging = []
        self.commits = []
    def add(self, arq):
        if arq not in self.staging: self.staging.append(arq)
    def commit(self, msg):
        if not self.staging: raise ValueError()
        c = Commit(len(self.commits)+1, msg, self.staging)
        self.commits.append(c)
        self.staging = []
    def status(self):
        return {"staged": len(self.staging), "total_commits": len(self.commits)}
    def executar_script(self, comandos):
        for cmd, arg in comandos:
            if cmd == "ADD": self.add(arg)
            elif cmd == "COMMIT": self.commit(arg)
        return self.status()

